bc&amp;quot;},&amp;quot;ts_fgc2&amp;quot;:{&amp;quot;clr_type&amp;quot;:0,&amp;quot;hclr_color&amp;quot;:&amp;quot;#11734b&amp;quot;},&amp;quot;ts_bd_i&amp;quot;:false,&amp;quot;ts_fs_i&amp;quot;:false,&amp;quot;ts_ff_i&amp;quot;:false,&amp;quot;ts_it_i&amp;quot;:false,&amp;quot;ts_sc_i&amp;quot;:false,&amp;quot;ts_st_i&amp;quot;:false,&amp;quot;ts_un_i&amp;quot;:false,&amp;quot;ts_va_i&amp;quot;:false,&amp;quot;ts_bgc2_i&amp;quot;:false,&amp;quot;ts_fgc2_i&amp;quot;:false},&amp;quot;di-cv&amp;quot;:{&amp;quot;dicv_v&amp;quot;:0,&amp;quot;dicv_ft&amp;quot;:0}},{&amp;quot;di-id&amp;quot;:&amp;quot;dropdownItem.32mr5yqb0km&amp;quot;,&amp;quot;di-v&amp;quot;:&amp;quot;Extensive: 51%-75%&amp;quot;,&amp;quot;di-dv&amp;quot;:&amp;quot;Extensive: 51%-75%&amp;quot;,&amp;quot;di-ts&amp;quot;:{&amp;quot;ts_bd&amp;quot;:false,&amp;quot;ts_fs&amp;quot;:11,&amp;quot;ts_ff&amp;quot;:&amp;quot;Arial&amp;quot;,&amp;quot;ts_it&amp;quot;:false,&amp;quot;ts_sc&amp;quot;:false,&amp;quot;ts_st&amp;quot;:false,&amp;quot;ts_tw&amp;quot;:400,&amp;quot;ts_un&amp;quot;:false,&amp;quot;ts_va&amp;quot;:&amp;quot;nor&amp;quot;,&amp;quot;ts_bgc2&amp;quot;:{&amp;quot;clr_type&amp;quot;:0,&amp;quot;hclr_color&amp;quot;:&amp;quot;#d4edbc&amp;quot;},&amp;quot;ts_fgc2&amp;quot;:{&amp;quot;clr_type&amp;quot;:0,&amp;quot;hclr_color&amp;quot;:&amp;quot;#11734b&amp;quot;},&amp;quot;ts_bd_i&amp;quot;:false,&amp;quot;ts_fs_i&amp;quot;:false,&amp;quot;ts_ff_i&amp;quot;:false,&amp;quot;ts_it_i&amp;quot;:false,&amp;quot;ts_sc_i&amp;quot;:false,&amp;quot;ts_st_i&amp;quot;:false,&amp;quot;ts_un_i&amp;quot;:false,&amp;quot;ts_va_i&amp;quot;:false,&amp;quot;ts_bgc2_i&amp;quot;:false,&amp;quot;ts_fgc2_i&amp;quot;:false},&amp;quot;di-cv&amp;quot;:{&amp;quot;dicv_v&amp;quot;:0,&amp;quot;dicv_ft&amp;quot;:0}},{&amp;quot;di-id&amp;quot;:&amp;quot;dropdownItem.8vlix7ndlh7v&amp;quot;,&amp;quot;di-v&amp;quot;:&amp;quot;Heavy: 76%-100%&amp;quot;,&amp;quot;di-dv&amp;quot;:&amp;quot;Heavy: 76%-100%&amp;quot;,&amp;quot;di-ts&amp;quot;:{&amp;quot;ts_bd&amp;quot;:false,&amp;quot;ts_fs&amp;quot;:11,&amp;quot;ts_ff&amp;quot;:&amp;quot;Arial&amp;quot;,&amp;quot;ts_it&amp;quot;:false,&amp;quot;ts_sc&amp;quot;:false,&amp;quot;ts_st&amp;quot;:false,&amp;quot;ts_tw&amp;quot;:400,&amp;quot;ts_un&amp;quot;:false,&amp;quot;ts_va&amp;quot;:&amp;quot;nor&amp;quot;,&amp;quot;ts_bgc2&amp;quot;:{&amp;quot;clr_type&amp;quot;:0,&amp;quot;hclr_color&amp;quot;:&amp;quot;#d4edbc&amp;quot;},&amp;quot;ts_fgc2&amp;quot;:{&amp;quot;clr_type&amp;quot;:0,&amp;quot;hclr_color&amp;quot;:&amp;quot;#11734b&amp;quot;},&amp;quot;ts_bd_i&amp;quot;:false,&amp;quot;ts_fs_i&amp;quot;:false,&amp;quot;ts_ff_i&amp;quot;:false,&amp;quot;ts_it_i&amp;quot;:false,&amp;quot;ts_sc_i&amp;quot;:false,&amp;quot;ts_st_i&amp;quot;:false,&amp;quot;ts_un_i&amp;quot;:false,&amp;quot;ts_va_i&amp;quot;:false,&amp;quot;ts_bgc2_i&amp;quot;:false,&amp;quot;ts_fgc2_i&amp;quot;:false},&amp;quot;di-cv&amp;quot;:{&amp;quot;dicv_v&amp;quot;:0,&amp;quot;dicv_ft&amp;quot;:0}}]}},&amp;quot;ddefe-t&amp;quot;:&amp;quot;Travel&amp;quot;,&amp;quot;type&amp;quot;:&amp;quot;dropdown&amp;quot;}&quot;&gt;Minimal: 1%-10%&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;
&lt;hr&gt;
&lt;div class=&quot;c-message_kit__blocks c-message_kit__blocks--rich_text&quot;&gt;
&lt;div class=&quot;c-message__message_blocks c-message__message_blocks--rich_text&quot; data-qa=&quot;message-text&quot;&gt;
&lt;div class=&quot;p-block_kit_renderer&quot; data-qa=&quot;block-kit-renderer&quot;&gt;
&lt;div class=&quot;p-block_kit_renderer__block_wrapper p-block_kit_renderer__block_wrapper--first&quot;&gt;
&lt;div class=&quot;p-rich_text_block&quot;&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;
&lt;p&gt;&lt;strong&gt;Benefits and Perks&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Comprehensive healthcare suite including medical, dental, vision, life, and disability plans. Domestic partners who have been residing together at least one year are also eligible to participate.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Health Savings and Flexible Spending Healthcare and Dependent Care Accounts available.&lt;/li&gt;
&lt;li&gt;Rich retirement benefits, including an immediately vested employer safe harbor match.&lt;/li&gt;
&lt;li&gt;Generous paid parental leave as well as a phased return to work.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Flexible vacation policy in addition to paid company holidays.&lt;/li&gt;
&lt;li&gt;Total Wellness Program providing numerous resources for overall wellbeing&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;Don’t meet every single requirement? Studies have shown that women and/or people of color are less likely to apply to a job unless they meet every qualification. At May Mobility, we’re committed to building a diverse, inclusive, and authentic workforce, so if you’re excited about this role but your previous experience doesn’t align perfectly with every qualification, we encourage you to apply anyway! You may be the perfect candidate for this or another role at May.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;p&gt;&lt;em&gt;Want to learn more about our culture &amp;amp; benefits? Check out our&amp;nbsp;&lt;a href=&quot;https://maymobility.com/careers/&quot; target=&quot;_blank&quot;&gt;website&lt;/a&gt;!&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;May Mobility is an equal opportunity employer.&amp;nbsp; All applicants for employment will be considered without regard to race, color, religion, sex, national origin, age, disability, sexual orientation, gender identity or expression, veteran status, genetics or any other legally protected basis. &amp;nbsp; Below, you have the opportunity to share your preferred gender pronouns, gender, ethnicity, and veteran status with May Mobility to help us identify areas of improvement in our hiring and recruitment processes. Completion of these questions is entirely voluntary.&amp;nbsp; Any information you choose to provide will be kept confidential, and will not impact the hiring decision in any way. If you believe that you will need any type of accommodation, please let us know.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;em&gt;Note to Recruitment Agencies:&lt;/em&gt;&lt;/strong&gt;&lt;em&gt;&amp;nbsp;May Mobility does not accept unsolicited agency resumes. Furthermore, May Mobility does not pay placement fees for candidates submitted by any agency other than its approved partners.&lt;/em&gt;&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;Salary Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$135,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$160,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;em&gt;May Mobility uses automated tools to support — but not replace — human judgment in our recruiting process,&amp;nbsp;to find out more please click&amp;nbsp;&lt;a href=&quot;https://drive.google.com/file/d/1eGgErDdZ99HVoyxBrVpVUjhdUcmKogki/view?usp=drive_link&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://drive.google.com/file/d/1eGgErDdZ99HVoyxBrVpVUjhdUcmKogki/view?usp%3Ddrive_link&amp;amp;source=gmail&amp;amp;ust=1783531371699000&amp;amp;usg=AOvVaw1I0-jRwBKi4mKGIvZGCIUS&quot;&gt;here&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Waymo is an autonomous driving technology company with the mission to be the world&#39;s most trusted driver. Since its start as the Google Self-Driving Car Project in 2009, Waymo has focused on building the Waymo Driver—The World&#39;s Most Experienced Driver™—to improve access to mobility while saving thousands of lives now lost to traffic crashes. The Waymo Driver powers Waymo’s fully autonomous ride-hail service and can also be applied to a range of vehicle platforms and product use cases. The Waymo Driver has provided over ten million rider-only trips, enabled by its experience autonomously driving over 100 million miles on public roads and tens of billions in simulation across 15+ U.S. states.&lt;/p&gt;&lt;/div&gt;&lt;p style=&quot;text-align: left;&quot;&gt;The Software Quality Operations (SWQOPS) team is at the heart of ensuring the safety, reliability, and quality of the Waymo Driver. Our mission is to build an adaptable and scalable operation, increasingly powered by AI, to deliver the crucial insights necessary to confidently deploy and grow Waymo&#39;s autonomous vehicle service.&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;Waymo is experiencing unprecedented growth, rapidly expanding into new cities and launching new vehicle platforms. SWQOps, particularly our Technical&lt;strong&gt; &lt;/strong&gt;Specialists, are critical to this expansion, enabling us to scale safely and efficiently.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Why this team is Essential to Waymo&#39;s Success:&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;nbsp; &amp;nbsp; In this role you will:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Partner with Engineering to design, test, and deploy cutting-edge Machine Learning (ML) and Generative AI (Gen-AI) models and tools to drive step-change improvements in issue discovery &amp;amp; detection, triage efficiency, and quality assurance.&lt;/li&gt;
&lt;li&gt;Leverage AI-powered insights and traditional triage signals to proactively identify emerging on-road issue trends, new risk scenarios, and edge cases. Develop and refine data-driven strategies for issue discovery and monitoring, enhanced by ML model outputs&lt;/li&gt;
&lt;li&gt;Serve as the key link between AI/ML development and operational execution. Define and document new policies, guidelines, and Standard Operating Procedures (SOPs) that integrate AI tools and insights into daily vendor workflows.&lt;/li&gt;
&lt;li&gt;Design and implement robust quality control processes for both human and AI-generated outputs. Perform meta-quality checks, validate the integrity of vendor work, and provide feedback to improve both human and model performance.&lt;/li&gt;
&lt;li&gt;Act as the subject matter expert for our Software Quality Operations, working closely with stakeholders, program leads, and vendor teams to ensure seamless adoption and maximum impact of AI/ML advancements in our quality processes. Be the trusted source for creating and updating technical policies, guidelines, and standard operating procedures for new scopes, platforms, and driving signals&lt;/li&gt;
&lt;li&gt;Provide technical leadership and consultation to stakeholders to enhance our workflows and quality. You&#39;ll be at the forefront of identifying and escalating issues with our tools, providing technical requirements to engineering, and driving user testing to support the development and deployment of new tooling features.&lt;/li&gt;
&lt;li&gt;A proven ability to work in a fast-paced, high-stress environment while maintaining good judgment.&lt;/li&gt;
&lt;li&gt;Excellent communication and interpersonal skills to effectively collaborate with a wide range of individuals in a diverse and dynamic work environment.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;nbsp; &amp;nbsp; &amp;nbsp;You have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;BS/BA degree or 4 years of relevant work experience in AV Software Quality Operations&lt;/li&gt;
&lt;li&gt;Increased competency in supporting all phases of the machine learning development lifecycle, from data preparation and training to validation, deployment, and continuous monitoring.&lt;/li&gt;
&lt;li&gt;Experience with ML testing and validation, including dataset quality assurance, bias detection, edge-case scenario testing, and performance evaluation using statistical metrics.&lt;/li&gt;
&lt;li&gt;Ability to quickly learn and implement new concepts and utilize proprietary tools. Strong understanding of driving rules and regulations.&lt;/li&gt;
&lt;li&gt;Must have the ability to provide occasional on-call availability for evenings, weekends, and holidays, as well as the flexibility to attend meetings outside of standard hours to collaborate with our global team.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;nbsp; &amp;nbsp; &amp;nbsp; We prefer:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Demonstrated strong execution with ability to drive outcomes.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience working with offshore teams / multiple local operations hubs.&lt;/li&gt;
&lt;li&gt;Basic SQL querying.&lt;/li&gt;
&lt;li&gt;Competency in LLM / transformer models, and / or ML for robotics domain experience.&lt;/li&gt;
&lt;li&gt;A greater focus on using your subject matter expertise for results analysis and direct customer consultation in the development of new and improved. solutions.&lt;/li&gt;
&lt;li&gt;Self-motivated with basic skills in task planning and time management.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;In accordance with Washington state law, we are highlighting our comprehensive benefits package, which is available to all eligible US based employees. Benefits for this role include:&lt;/em&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;em&gt;Health, dental, vision, life, disability insurance&lt;/em&gt;&lt;/li&gt;
&lt;li&gt;&lt;em&gt;Retirement Benefits: 401(k) with company match&lt;/em&gt;&lt;/li&gt;
&lt;li&gt;&lt;em&gt;Paid Time Off: 20 days of vacation per year, accruing at a rate of 6.15 hours per pay period for the first five years of employment&lt;/em&gt;&lt;/li&gt;
&lt;li&gt;&lt;em&gt;Sick Time: 40 hours/year (statutory, where applicable); 5 days/event (discretionary)&lt;/em&gt;&lt;/li&gt;
&lt;li&gt;&lt;em&gt;Maternity Leave (Short-Term Disability + Baby Bonding): 28-30 weeks&lt;/em&gt;&lt;/li&gt;
&lt;li&gt;&lt;em&gt;Baby Bonding Leave: 18 weeks&lt;/em&gt;&lt;/li&gt;
&lt;li&gt;&lt;em&gt;Holidays: 13 paid days per year&lt;/em&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;This is a remote position.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;(Remote jobs only - Please note that Waymo may not be able to employ remotely in all locations. Please speak with your recruiter about your preferred location for remote work when you begin the interview process.))&lt;/em&gt;&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;The expected base salary range for this full-time position across US locations is listed below. Actual starting pay will be based on job-related factors, including exact work location, experience, relevant training and education, and skill level. Your recruiter can share more about the specific salary range for the role location or, if the role can be performed remote, the specific salary range for your preferred location, during the hiring process.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Waymo employees are also eligible to participate in Waymo’s discretionary annual bonus program, equity incentive plan, and generous Company benefits program, subject to eligibility requirements.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Salary Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$130,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$160,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Waymo is an autonomous driving technology company with the mission to be the world&#39;s most trusted driver. Since its start as the Google Self-Driving Car Project in 2009, Waymo has focused on building the Waymo Driver—The World&#39;s Most Experienced Driver™—to improve access to mobility while saving thousands of lives now lost to traffic crashes. The Waymo Driver powers Waymo’s fully autonomous ride-hail service and can also be applied to a range of vehicle platforms and product use cases. The Waymo Driver has provided over ten million rider-only trips, enabled by its experience autonomously driving over 100 million miles on public roads and tens of billions in simulation across 15+ U.S. states.&lt;/p&gt;&lt;/div&gt;&lt;p data-pm-slice=&quot;1 1 []&quot;&gt;The Perception team builds the system which learns the spatial-temporal representation and their semantic meanings of the surrounding environment of the autonomously driving vehicle (ADV), i.e., the system that “perceives” the world around the car. We work jointly with downstream teams on the optimization and integration into the Waymo Driver. We conduct our own research to address real-world problems and collaborate with research teams at Alphabet. We have access to millions of miles of driving data from a diverse set of sensors, enabling engineers like you to (1) develop methods for efficiently and continuously learning from large scale real-world data, to (2) develop models and model training at scale, to (3) analyze real-world behavior and develop systems for handling the complexities of interacting with the real-world, and (4) optimize models for our onboard and offboard hardware.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You will:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Design VLM/LLM model architecture and drive strong alignment between model architectures and hardware architectures.&lt;/li&gt;
&lt;li&gt;Optimize model performance for on-device use cases (memory, power, compute constrained environments).&lt;/li&gt;
&lt;li&gt;Engage directly with research, software engineering, hardware engineering, and product teams to deliver end-to-end solutions.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;You have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;7+ years of experience in Machine Learning, with a focus on large-scale model development (LLM, VLM, or similar foundation models).&lt;/li&gt;
&lt;li&gt;Proven expertise in low-latency on-device inference techniques and a deep understanding of hardware acceleration.&lt;/li&gt;
&lt;li&gt;Extensive experience with deep learning frameworks (e.g. PyTorch, JAX) and large-scale model training.&lt;/li&gt;
&lt;li&gt;A track record of operating effectively under ambiguity, setting direction amid rapidly evolving research and technical constraints&lt;/li&gt;
&lt;li&gt;Experience applying large language models or foundation models in complex, safety-critical domains (e.g., autonomy, robotics, or other high-reliability systems)&lt;/li&gt;
&lt;li&gt;Master&#39;s degree in Computer Science, Electrical Engineering, or a related field, or equivalent practical experience.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;We prefer:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Familiarity with large-scale data curation and quality assurance processes for multimodal datasets.&lt;/li&gt;
&lt;li&gt;Background in autonomous vehicle perception, motion planning, or decision-making systems.&lt;/li&gt;
&lt;li&gt;Publications in top-tier machine learning or computer vision conferences (e.g., NeurIPS, ICML, CVPR, ICCV, ECCV).&lt;/li&gt;
&lt;li&gt;PhD in a relevant field.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;The expected base salary range for this full-time position across US locations is listed below. Actual starting pay will be based on job-related factors, including exact work location, experience, relevant training and education, and skill level. Your recruiter can share more about the specific salary range for the role location or, if the role can be performed remote, the specific salary range for your preferred location, during the hiring process.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Waymo employees are also eligible to participate in Waymo’s discretionary annual bonus program, equity incentive plan, and generous Company benefits program, subject to eligibility requirements.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Salary Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$298,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$368,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Waymo is an autonomous driving technology company with the mission to be the world&#39;s most trusted driver. Since its start as the Google Self-Driving Car Project in 2009, Waymo has focused on building the Waymo Driver—The World&#39;s Most Experienced Driver™—to improve access to mobility while saving thousands of lives now lost to traffic crashes. The Waymo Driver powers Waymo’s fully autonomous ride-hail service and can also be applied to a range of vehicle platforms and product use cases. The Waymo Driver has provided over ten million rider-only trips, enabled by its experience autonomously driving over 100 million miles on public roads and tens of billions in simulation across 15+ U.S. states.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;content-intro&quot;&gt;
&lt;p&gt;The Planner Evaluation team works on one of the key challenges in autonomous driving: measuring and improving the quality of the software that drives the car. We are looking for experienced data-minded software engineers and data scientists to help us improve how we characterize and evaluate changes to the Onboard software stack (Planner, Perception, etc). If you are passionate about autonomous vehicles and how to use rich, complex data to drive decision making, this is the role for you!&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;This role follows a hybrid work schedule and reports to &lt;em&gt;a&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;Sr. Staff &lt;/em&gt;&lt;em&gt;Engineering Manager.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You will:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Develop signals to measure the performance and driving qualities of the Waymo driver, using a range of techniques including statistics, math, physics, algorithms and machine learning.&lt;/li&gt;
&lt;li&gt;Use simulation creatively and mine real world driving logs to measure&amp;nbsp; driving performance.&lt;/li&gt;
&lt;li&gt;Design and implement methods to make a stronger connection between onboard software changes and simulated outcomes.&lt;/li&gt;
&lt;li&gt;Champion code health and best practices in a large and complex code base.&lt;/li&gt;
&lt;li&gt;Analyze data and make recommendations on how to improve metric quality and interpretability.&lt;/li&gt;
&lt;li&gt;Collaborate with other engineers, data scientists, statisticians and the leadership team to deliver evaluation products and help make data driven decisions.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;BS in Computer Science, Robotics, Statistics, Physics, Math or another quantitative area&lt;/li&gt;
&lt;li&gt;Strong self-motivation to navigate complex systems and pursue open-ended problems to completion&lt;/li&gt;
&lt;li&gt;1+ years of industry experience with&lt;br&gt;
&lt;ul&gt;
&lt;li&gt;Navigating and modifying a large code base containing a variety of languages, such as C++, Python and SQL&lt;/li&gt;
&lt;li&gt;Performing statistical analyses&lt;/li&gt;
&lt;li&gt;Building data processing pipelines&lt;/li&gt;
&lt;li&gt;Writing, reviewing, and merging code following industry standards for code health and maintainability&lt;/li&gt;
&lt;li&gt;Quant/data fluency is a top requirement&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;We prefer:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience coding in C++&lt;/li&gt;
&lt;li&gt;Experience with ML&lt;/li&gt;
&lt;li&gt;Experience with A/B experiment infrastructure&lt;/li&gt;
&lt;li&gt;Experience building and validating metrics to measure quality in complex systems&lt;/li&gt;
&lt;li&gt;Exposure to ad-hoc data analysis tools for rapid modeling and prototyping&lt;/li&gt;
&lt;li&gt;Experience working in the AV industry&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;#LI-Hybrid&lt;/p&gt;
&lt;/div&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;The expected base salary range for this full-time position across US locations is listed below. Actual starting pay will be based on job-related factors, including exact work location, experience, relevant training and education, and skill level. Your recruiter can share more about the specific salary range for the role location or, if the role can be performed remote, the specific salary range for your preferred location, during the hiring process.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Waymo employees are also eligible to participate in Waymo’s discretionary annual bonus program, equity incentive plan, and generous Company benefits program, subject to eligibility requirements.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Salary Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$170,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$216,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;

&lt;p&gt;&lt;strong&gt;Who We Are&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Nuro believes self-driving vehicles are the most immediate and profound opportunity for AI to drive positive change in the physical world. Safer streets, more time for what matters, and easier access to the world around us, that’s why we’re building a universal autonomy platform: self-driving for all roads and all rides.&lt;br&gt;&lt;br&gt;Founded in 2016, Nuro is a physical AI company developing Level 4 autonomous driving technology for a wide range of vehicles, use cases, and markets. Powered by the Nuro Driver™, our universal autonomy platform enables the global mobility ecosystem to deploy autonomy at scale, from robotaxis and logistics fleets to personal vehicles.&lt;br&gt;&lt;br&gt;With years of real-world deployment experience and a flexible, partner-led business model, Nuro is working toward a future where millions of autonomous vehicles powered by our technology help make everyday life safer, easier, and more connected.&lt;br&gt;&lt;br&gt;Nuro has raised over $2B in capital from Uber, NVIDIA, Google, Softbank, Fidelity, T. Rowe Price, and other leading investors.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the Role&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Nuro is looking for a People Systems Analyst to drive Workday operations, reporting, and workforce analytics for our People Operations team. You will own production support alongside two other analysts, build dashboards and analytics for leadership, and keep core people operations running. We are a lean, high-impact team that has invested heavily in AI-powered automation, and we are looking for someone who brings real Workday experience but thrives in a scrappy, fast-paced environment where you build, iterate, and ship.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the Work&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Workday Systems and Configuration&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Provide Tier 1 production support for Workday, including business process definitions and validations, EIB files, calculated fields, and transactional processing&lt;/li&gt;
&lt;li&gt;With direction from the Sr. Workday Analyst, configure, test, and implement new release features in implementation tenants prior to release dates&lt;/li&gt;
&lt;li&gt;Write test scripts and participate across every phase of the testing cycle for new features, enhancements, and fixes&lt;/li&gt;
&lt;li&gt;Support troubleshooting, modifications, and enhancements for integrations under the Sr. Analyst&#39;s direction&lt;/li&gt;
&lt;li&gt;Conduct routine data audits across HR systems, resolve inconsistencies that cause integration errors, and support the data governance framework for People data&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Analytics and Reporting Automation&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Own the monthly executive KPI reporting process end to end, from data collection and analysis through stakeholder delivery&lt;/li&gt;
&lt;li&gt;Build custom Workday reports and deep-dive analyses, leveraging AI to accelerate insight generation&lt;/li&gt;
&lt;li&gt;Partner with stakeholders to scope reporting needs and deliver ad hoc workforce analytics&lt;/li&gt;
&lt;li&gt;Continuously streamline reporting workflows through AI tools and automation to reduce manual data pulls and scale the team&#39;s analytics capacity&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;People Operations and Process Improvement&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Support people operations workflows, documentation, and stakeholder communication&lt;/li&gt;
&lt;li&gt;Provide backup coverage for core people operations workflows during peak periods (onboarding, offboarding, internal mobility)&lt;/li&gt;
&lt;li&gt;Monitor service desk utilization and identify opportunities for operational improvement and automation, partnering with the team&#39;s AI and automation resources&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;About You&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;3+ years of experience in People Operations, People Analytics, HRIS or a comparable role&lt;/li&gt;
&lt;li&gt;Workday experience required with exposure to at least one module; experience with time tracking, absence and benefits are a plus&lt;/li&gt;
&lt;li&gt;Comfortable writing test scripts, building EIB files, and troubleshooting configuration issues independently&lt;/li&gt;
&lt;li&gt;Analytically minded with strong attention to detail and a bias toward data integrity&lt;/li&gt;
&lt;li&gt;Strong sense of discretion and ethics when handling sensitive People data&lt;/li&gt;
&lt;li&gt;Curious about technology, automation, and AI-assisted workflows&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;At Nuro, your base pay is one part of your total compensation package. For this position, the reasonably expected base pay range is between $99,220 and $149,330 for the level at which this job has been scoped. Your base pay will depend on several factors, including your experience, qualifications, education, location, and skills. In the event that you are considered for a different level, a higher or lower pay range would apply. This position is also eligible for an annual performance bonus, equity, and a competitive benefits package.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;At Nuro, we celebrate differences and are committed to a diverse workplace that fosters inclusion and psychological safety for all employees. Nuro is proud to be an equal opportunity employer and expressly prohibits any form of workplace discrimination based on race, color, religion, gender, sexual orientation, gender identity or expression, national origin, age, genetic information, disability, veteran status, or any other legally protected characteristics.&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Kodiak Robotics, Inc. was founded in 2018 and has become a leader in autonomous ground transportation committed to a safer and more efficient future for all. The company has developed an artificial intelligence (AI) powered technology stack purpose-built for commercial trucking and the public sector. The company delivers freight daily for its customers across the southern United States using its autonomous technology. In 2024, Kodiak became the first known company to publicly announce delivering a driverless semi-truck to a customer. Kodiak is also leveraging its commercial self-driving software to develop, test and deploy autonomous capabilities for the U.S. Department of Defense.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;We are seeking a hands-on Simulation Operations Specialist to join the Software Quality team. In this role, you will drive improvements across large-scale simulation sets, enhance simulation workflows and tools, and help advance safe and reliable autonomous trucking technology.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;In this role, you will:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Develop test plans and create simulations to test the behavior of our autonomous trucks.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Actively run daily simulation operations, including scenario execution, triage, and reporting.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Improve efficiency in test planning, scenario execution, and results tracking across large-scale simulation suites.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Partner with engineering teams to ensure simulation scenarios accurately reflect real-world conditions.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Work closely with systems engineers on structured test design and execution, ensuring comprehensive coverage of safety-critical and edge-case scenarios.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Share actionable insights from simulation results with autonomy software engineers to accelerate software development and validation.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Collaborate with infrastructure and tools teams to enhance automation, debugging, and scaling of simulations.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;What you’ll bring:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;2+ years of experience in autonomous vehicle or robotics industry.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Bachelor’s degree in Engineering, Computer Science or related field.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;3+ years of experience in simulation, QA, or test automation, ideally in robotics or autonomous systems.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Familiarity with python or C++ programming.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Hands-on experience with simulation workflows or large-scale simulation testing environments.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Strong problem-solving skills and ability to dive into technical details.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Passion for autonomous technology and improving safety and efficiency through simulation.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Familiarity with structured test planning and execution; experience working with systems engineers preferred.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Experience with Applied Intuition tools is a plus.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Great communicator with experience writing clear, concise, and detailed communication&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Love of robots - You love to be in, around, or near robots&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p class=&quot;p2&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;What we offer:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Competitive compensation package including equity and annual bonuses&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Excellent Medical, Dental, and Vision plans through Kaiser Permanente, Cigna, and&amp;nbsp; MetLife (including a medical plan with infertility benefits)&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;MetLife Legal Services, Identity &amp;amp; Fraud Protection, Hospital Indemnity Insurance, Accident Insurance, &amp;amp; Critical Illness Insurance&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Flexible PTO, 10 paid holidays, and generous parental leave policies&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Our office is centrally located in Mountain View, CA&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Office perks: dog-friendly, free catered lunch, a fully stocked kitchen, and free EV charging&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Long Term Disability, Short Term Disability, Life Insurance&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Wellbeing Benefits - Headspace through Cigna, Calm through Kaiser, One Medical, Gympass, Spring Health through Cigna, Rula (mental health navigation)&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Fidelity 401(k)&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Commuter, FSA, Dependent Care FSA, HSA&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Various incentive programs (referral bonuses, patent bonuses, etc.)&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;The pay range listed below reflects the base salary&amp;nbsp;&lt;strong data-stringify-type=&quot;bold&quot;&gt;in our SF/Silicon Valley location,&amp;nbsp;&lt;/strong&gt;across several internal levels. Actual starting pay will be based on job-related factors including: work location, experience, relevant training, education, skill level and performance during interview. Total compensation at Kodiak includes base pay, equity, bonus and a competitive benefits package&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;California Pay Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$130,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$145,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;At Kodiak, we strive to build a diverse community working towards our common company goals in a safe and collaborative environment where harassment of any kind is strictly prohibited. Kodiak is committed to equal opportunity employment regardless of race, ethnicity, religion, gender identity, sexual orientation, age, disability, or veteran status, or any other basis protected by applicable law.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;In alignment with its business operations, Kodiak adheres to all relevant statutes, regulations, and administrative prerequisites. Accordingly, roles that carry more sensitive requirements may be limited to candidates that can satisfy additional scrutiny and eligibility for such positions may hinge on verification of a candidate’s residence, U.S. person status, and/or citizenship status. Should the position require, and Kodiak determines that a candidate’s residence, U.S. person status, and/or citizenship status necessitate an export license, bar the candidate from the position, or otherwise fall under national security-related restrictions, Kodiak will consider the candidate for alternative positions unaffected by such restrictions, under terms and conditions set forth at Kodiak’s sole discretion, or, as an alternative, opt not to proceed with the candidate’s application. If applicable, Kodiak may provide visa sponsorship for eligible candidates.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;em&gt;We use a third-party AI tool (Endorsed) to assist in the initial screening of applications. As part of the evaluation process, we provide Endorsed with job requirements and candidate-submitted applications. Final hiring decisions are made by our human recruitment team, and no automated system makes the ultimate decision regarding hiring. Certain features of the platform may qualify it as an Automated Employment Decision Tool (AEDT) under applicable regulations. We began using Endorsed on January 1, 2026. You can review the independent bias audit report covering our use of Endorsed [here](&lt;/em&gt;&lt;em&gt;&lt;a href=&quot;https://endorsed.com/local-law-144&quot; target=&quot;_blank&quot; data-sk=&quot;tooltip_parent&quot;&gt;https://endorsed.com/local-law-144&lt;/a&gt;&lt;/em&gt;&lt;em&gt;). By submitting your application, you acknowledge that your application may be processed by AI systems as part of the screening and selection process. If you have any questions or would like to request a separate review of your application, please contact &lt;/em&gt;&lt;em&gt;&lt;a href=&quot;mailto:careers@kodiak.ai&quot; target=&quot;_blank&quot; data-sk=&quot;tooltip_parent&quot;&gt;careers@kodiak.ai&lt;/a&gt;&lt;/em&gt;&lt;em&gt; with &quot;Separate Review Request&quot; in the email subject line.&lt;/em&gt;&lt;/div&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;

&lt;p&gt;&lt;strong&gt;Who We Are&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Nuro believes self-driving vehicles are the most immediate and profound opportunity for AI to drive positive change in the physical world. Safer streets, more time for what matters, and easier access to the world around us, that’s why we’re building a universal autonomy platform: self-driving for all roads and all rides.&lt;br&gt;&lt;br&gt;Founded in 2016, Nuro is a physical AI company developing Level 4 autonomous driving technology for a wide range of vehicles, use cases, and markets. Powered by the Nuro Driver™, our universal autonomy platform enables the global mobility ecosystem to deploy autonomy at scale, from robotaxis and logistics fleets to personal vehicles.&lt;br&gt;&lt;br&gt;With years of real-world deployment experience and a flexible, partner-led business model, Nuro is working toward a future where millions of autonomous vehicles powered by our technology help make everyday life safer, easier, and more connected.&lt;br&gt;&lt;br&gt;Nuro has raised over $2B in capital from Uber, NVIDIA, Google, Softbank, Fidelity, T. Rowe Price, and other leading investors&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the Role&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Nuro takes a machine-learning-first approach to autonomous driving technology. In an ML-first system, the overall system performance depends heavily on the quantity and diversity of its training and evaluation data.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;The team plays a crucial role in the advancement of autonomous driving systems by creating a scalable and reliable data infrastructure. This infrastructure is designed to produce training and evaluation data derived from both on-road collected logs and simulation logs. Additionally, the team collaborates closely with system engineers to thoroughly validate the autonomous driving system before its deployment.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the Work&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Design and develop unified, introspectable, large-scale batch and streaming data pipelines that can ingest and process data across a wide range of use cases relevant to evaluation.&lt;/li&gt;
&lt;li&gt;Create and implement a storage system capable of accommodating both the large volume and diverse range of evaluation and performance metrics.&lt;/li&gt;
&lt;li&gt;Construct intuitive dashboards and reports to present evaluation results, facilitating straightforward comparisons that highlight both improvements and regressions of the ML components and the overall system.&lt;/li&gt;
&lt;li&gt;Develop and maintain continuous testing and monitoring systems to guarantee the integrity and resilience of our data and associated data pipelines.&lt;/li&gt;
&lt;li&gt;Develop data mining tools with applied ML techniques to support data discovery needs from Autonomy including Perception, Behavior, and Mapping&lt;/li&gt;
&lt;li&gt;Develop data annotation tools to support first-party and third-party labeling workforce to provide high fidelity perception, mapping, and driving trajectory labels&lt;/li&gt;
&lt;li&gt;Scale data annotation labels with applied State-of-the-art ML techniques&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;About You&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;You have a degree in BS, MS.c or Ph.D, plus 4 years of relevant work experience&lt;/li&gt;
&lt;li&gt;Strong proficiency in Python or similar languages&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Domain experience:&lt;/strong&gt; Experience working with large-scale data and building scalable &amp;amp; reliable systems/data pipelines; ability to understand and design complex systems&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Engineering leadership:&lt;/strong&gt; Experience setting team or project product and technical vision, timelines, and prioritization; being a Technical Lead, mentoring and support junior engineers&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Technical excellence:&lt;/strong&gt; Ability and willingness to deep dive into implementation, driving technical standards and best practices across broader software organization&lt;/li&gt;
&lt;li&gt;A bachelor&#39;s degree in Computer Science, Electrical Engineering, or a closely related field&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Bonus Points&lt;/strong&gt;&amp;nbsp;&lt;em&gt;&lt;br&gt;&lt;/em&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Strong proficiency in C++ or other high-performance low-level languages&lt;/li&gt;
&lt;li&gt;Strong knowledge of GCP, GCS, BigQuery, or PostgreSQL&lt;/li&gt;
&lt;li&gt;Knowledge of data engineering, and its tooling and best practices&lt;/li&gt;
&lt;li&gt;Knowledge of batch and streaming data processing, warehousing, and analytics solutions&lt;/li&gt;
&lt;li&gt;Experience working with large-scale distributed data systems&lt;/li&gt;
&lt;li&gt;Experience with system &amp;amp; framework design&lt;/li&gt;
&lt;li&gt;Experience with data workflow orchestration platforms&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;At Nuro, your base pay is one part of your total compensation package. For this position, the reasonably expected pay range is between $193,930 and $352,290 for the level at which this job has been scoped. Your base pay will depend on several factors, including your experience, qualifications, education, location, and skills. In the event that you are considered for a different level, a higher or lower pay range would apply. This position is also eligible for an annual performance bonus, equity, and a competitive benefits package.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;At Nuro, we celebrate differences and are committed to a diverse workplace that fosters inclusion and psychological safety for all employees. Nuro is proud to be an equal opportunity employer and expressly prohibits any form of workplace discrimination based on race, color, religion, gender, sexual orientation, gender identity or expression, national origin, age, genetic information, disability, veteran status, or any other legally protected characteristics.&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;May Mobility is transforming cities through autonomous technology to create a safer, greener, more accessible world. Based in Ann Arbor, Michigan, May develops and deploys autonomous vehicles (AVs) powered by our innovative Multi-Policy Decision Making (MPDM) technology that literally reimagines the way AVs think.&lt;/span&gt;&lt;br&gt;&lt;br&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Our vehicles do more than just drive themselves - they provide value to communities, bridge public transit gaps and move people where they need to go safely, easily and with a lot more fun. We’re building the world’s best autonomy system to reimagine transit by minimizing congestion, expanding access and encouraging better land use in order to foster more green, vibrant and livable spaces. Since our founding in 2017, we’ve given more than 500,000 autonomous rides to real people around the globe. And we’re just getting started. We’re hiring people who share our passion for building the future, today, solving real-world problems and seeing the impact of their work. Join us.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;h1&gt;&lt;strong&gt;Job Summary&lt;/strong&gt;&lt;/h1&gt;
&lt;p&gt;We are seeking an experienced and data-driven Senior Systems Engineer II to lead the definition, optimization, and validation of next-generation Autonomous Vehicle capabilities.&lt;/p&gt;
&lt;p&gt;In this role, you will bridge the gap between high-level autonomy goals and actionable system requirements. You will be responsible for defining autonomous vehicle system requirements, designing complex scenario-based test suites in simulated and on-road environments, and building automated, KPI-driven reporting pipelines. The ideal candidate thrives at the intersection of systems engineering, automated testing, data analytics, and functional safety standards.&lt;/p&gt;
&lt;h1&gt;&lt;strong&gt;Essential Responsibilities&lt;/strong&gt;&lt;/h1&gt;
&lt;ul&gt;
&lt;li&gt;Define, document, and manage system and capability-level requirements with full end-to-end traceability leveraging requirement management, AV simulation, and data toolsets.&lt;/li&gt;
&lt;li&gt;Conduct in-depth Operational Design Domain (ODD) and route analyses to shape AV driving capabilities and sub-capabilities.&lt;/li&gt;
&lt;li&gt;Ensure designed scenarios align and comply with established industry standards and regulatory frameworks, such as Euro NCAP and NHTSA&lt;/li&gt;
&lt;li&gt;Drive and manage the driving simulation portfolio to ensure comprehensive validation coverage across the entire Operational Design Domain (ODD).&lt;/li&gt;
&lt;li&gt;Craft on-road and logical test scenarios designed specifically for evaluating autonomy features, system capabilities, and critical on-road events.&lt;/li&gt;
&lt;li&gt;Process and analyze real-world field events to close the loop by identifying simulation coverage gaps and creating representative simulation tests.&lt;/li&gt;
&lt;li&gt;Define clear, robust simulation specifications and requirements for cross-functional simulation teams to develop and build against.&lt;/li&gt;
&lt;li&gt;Analyze real-world and simulation results to identify performance trends, uncover potential issues, and provide insights for improvements&lt;/li&gt;
&lt;li&gt;Lead engineering process continuous improvement activities, proposing solutions and gaining buy-in from impacted teams&lt;/li&gt;
&lt;/ul&gt;
&lt;h1&gt;&lt;strong&gt;Skills and Abilities&lt;/strong&gt;&lt;/h1&gt;
&lt;p&gt;&lt;em&gt;Success in this role typically requires the following competencies:&lt;/em&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Strong analytical and problem solving skills&lt;/li&gt;
&lt;li&gt;Excellent written, verbal, and presentation skills&lt;/li&gt;
&lt;li&gt;Strong attention to detail and highly-organized&lt;/li&gt;
&lt;li&gt;Ability to multitask and adapt to shifting priorities in a fast-paced work environment&lt;/li&gt;
&lt;li&gt;Understanding of agile startup and engineering principles and mindset&lt;/li&gt;
&lt;li&gt;Ability to display systems thinking and attention to detail&lt;/li&gt;
&lt;li&gt;Detailed knowledge of requirements management and requirement-based design&lt;/li&gt;
&lt;li&gt;Curiosity to learn and desire to improve&lt;/li&gt;
&lt;/ul&gt;
&lt;h1&gt;&lt;strong&gt;Qualifications and Experience&lt;/strong&gt;&lt;/h1&gt;
&lt;p&gt;&lt;em&gt;Candidates most successful in this role typically hold the following qualifications or comparable knowledge or experience:&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;em&gt;Required&lt;/em&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Bachelor’s Degree from an accredited university&lt;/li&gt;
&lt;li&gt;6+ years experience in automotive systems engineering working on software, hardware, or combined hardware/software products and 3+ years systems engineering experience working on autonomous driving or advance driver assistance systems&lt;/li&gt;
&lt;li&gt;Strong knowledge of automotive and autonomous vehicle technologies&lt;/li&gt;
&lt;li&gt;Experience developing behavioral simulations for AV or ADAS features&lt;/li&gt;
&lt;li&gt;Experience with Python, SQL, and data analysis tools (e.g., Pandas, NumPy, Spark).&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;em&gt;Desirable&lt;/em&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;A Masters degree in Engineering or equivalent experience&lt;/li&gt;
&lt;li&gt;Experience working in a startup&lt;/li&gt;
&lt;li&gt;Practical awareness of functional safety principles, including ISO 26262, SOTIF, and HARA.&lt;/li&gt;
&lt;/ul&gt;
&lt;h1&gt;&lt;strong&gt;Physical Requirements&lt;/strong&gt;&lt;/h1&gt;
&lt;ul&gt;
&lt;li&gt;Standard office working conditions which includes but is not limited to:&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;Prolonged sitting&lt;/li&gt;
&lt;li&gt;Prolonged standing&lt;/li&gt;
&lt;li&gt;Prolonged computer use&lt;/li&gt;
&lt;/ul&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li&gt;Travel required? -&amp;nbsp; Minimal: 1%-10%&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;div class=&quot;c-message_kit__blocks c-message_kit__blocks--rich_text&quot;&gt;
&lt;div class=&quot;c-message__message_blocks c-message__message_blocks--rich_text&quot; data-qa=&quot;message-text&quot;&gt;
&lt;div class=&quot;p-block_kit_renderer&quot; data-qa=&quot;block-kit-renderer&quot;&gt;
&lt;div class=&quot;p-block_kit_renderer__block_wrapper p-block_kit_renderer__block_wrapper--first&quot;&gt;
&lt;div class=&quot;p-rich_text_block&quot;&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;
&lt;p&gt;&lt;strong&gt;Benefits and Perks&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Comprehensive healthcare suite including medical, dental, vision, life, and disability plans. Domestic partners who have been residing together at least one year are also eligible to participate.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Health Savings and Flexible Spending Healthcare and Dependent Care Accounts available.&lt;/li&gt;
&lt;li&gt;Rich retirement benefits, including an immediately vested employer safe harbor match.&lt;/li&gt;
&lt;li&gt;Generous paid parental leave as well as a phased return to work.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Flexible vacation policy in addition to paid company holidays.&lt;/li&gt;
&lt;li&gt;Total Wellness Program providing numerous resources for overall wellbeing&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;Don’t meet every single requirement? Studies have shown that women and/or people of color are less likely to apply to a job unless they meet every qualification. At May Mobility, we’re committed to building a diverse, inclusive, and authentic workforce, so if you’re excited about this role but your previous experience doesn’t align perfectly with every qualification, we encourage you to apply anyway! You may be the perfect candidate for this or another role at May.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;p&gt;&lt;em&gt;Want to learn more about our culture &amp;amp; benefits? Check out our&amp;nbsp;&lt;a href=&quot;https://maymobility.com/careers/&quot; target=&quot;_blank&quot;&gt;website&lt;/a&gt;!&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;May Mobility is an equal opportunity employer.&amp;nbsp; All applicants for employment will be considered without regard to race, color, religion, sex, national origin, age, disability, sexual orientation, gender identity or expression, veteran status, genetics or any other legally protected basis. &amp;nbsp; Below, you have the opportunity to share your preferred gender pronouns, gender, ethnicity, and veteran status with May Mobility to help us identify areas of improvement in our hiring and recruitment processes. Completion of these questions is entirely voluntary.&amp;nbsp; Any information you choose to provide will be kept confidential, and will not impact the hiring decision in any way. If you believe that you will need any type of accommodation, please let us know.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;em&gt;Note to Recruitment Agencies:&lt;/em&gt;&lt;/strong&gt;&lt;em&gt;&amp;nbsp;May Mobility does not accept unsolicited agency resumes. Furthermore, May Mobility does not pay placement fees for candidates submitted by any agency other than its approved partners.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;Salary Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$125,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$150,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;em&gt;May Mobility uses automated tools to support — but not replace — human judgment in our recruiting process,&amp;nbsp;to find out more please click&amp;nbsp;&lt;a href=&quot;https://drive.google.com/file/d/1eGgErDdZ99HVoyxBrVpVUjhdUcmKogki/view?usp=drive_link&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://drive.google.com/file/d/1eGgErDdZ99HVoyxBrVpVUjhdUcmKogki/view?usp%3Ddrive_link&amp;amp;source=gmail&amp;amp;ust=1783531371699000&amp;amp;usg=AOvVaw1I0-jRwBKi4mKGIvZGCIUS&quot;&gt;here&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

&lt;h3&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Who we are&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Gatik, the leader in autonomous middle-mile logistics, is revolutionizing the B2B supply chain with its autonomous transportation-as-a-service (ATaaS) solution and prioritizing safe, consistent deliveries while streamlining freight movement by reducing congestion. The company focuses on short-haul, B2B logistics for Fortune 500 retailers and in 2021 launched the world’s first fully driverless commercial transportation service with Walmart. Gatik&#39;s Class 3-7 autonomous trucks are commercially deployed across major markets, including Texas, Arkansas, and Ontario, Canada, driving innovation in freight transportation.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;The company&#39;s proprietary Level 4 autonomous technology, Gatik Carrier™, is custom-built to transport freight safely and efficiently between pick-up and drop-off locations on the middle mile. With robust capabilities in both highway and urban environments, Gatik Carrier™ serves as an all-encompassing solution that integrates advanced software and hardware powering the fleet, facilitating effortless integration into customers&#39; logistics operations.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;About the role&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Gatik is hiring a Senior/Staff Vehicle Harness Engineer who will be responsible for power and signal distribution on Gatik’s vehicles from concept to production. This individual will be tasked with creating engineering requirements and specifications for the harnesses as well as collaborating with suppliers and peers to deliver a functioning subsystem.Your area of expertise is the mechanical integration, fabrication and assembly of harness systems. You are excited being hands-on to apply your engineering knowledge and you are extremely comfortable with hand-tools and rapid prototyping fabrication. Independence, good communication and documentation skills are key to succeed in this role.&amp;nbsp;&lt;/span&gt;&lt;br&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;br&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;This role is onsite 5 days a week at our Santa Clara, CA office.&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;What you&#39;ll do&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Responsible for vehicle power and signal distribution on the vehicle.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Create engineering specifications for example requirements, schematics, CAD models, drawings for the vehicle harnesses&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Take ownership of the Device transmittal (DT) process&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Provide technical expertise on power, signal and data bus distribution as well as ground specification needed in autonomous vehicles; for example on GMSL,Automotive Ethernet, CAN, CAN-FD, low voltage high power applications&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Collaborate with cross functional team members to complete the system specification and fill gaps were needed&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Collaborate with suppliers/vendors as needed to build prototype and production vehicles&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Develop and refine tools and methods currently leveraged by the team&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Mentor junior engineers on the team in the principles of power and signal distribution and best practices&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;What we’re looking for&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;BS/MS in Mechanical Engineering or similar engineering discipline (MS preferred)&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;5+ years of hands-on experience with vehicle harnesses&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Delivered a system to production (preferred - from inception to production)&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Experience in the Automotive, Truck/Transportation and AV industry&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Experience with Zuken.E3 required&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Experience with advanced vehicle communication standards and requirements for example GMSL, Automotive Ethernet&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Ability to size and select the appropriate cables, connectors and fuses&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Ability to design mechanical components supporting the completion of the deliverable e.g. brackets, housings or pass-throughs&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Experience with CAD and/or drawing software (NX preferred)&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Strong troubleshooting skills&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Excellent communication and documentation skills&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Strong computer skills with programming and scripting experience, preferred&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Salary Range- $180,000- $25&lt;/span&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;0,000&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;More about Gatik&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Founded in 2017 by experts in autonomous vehicle technology, Gatik has rapidly expanded its presence to Mountain View, Dallas-Fort Worth, Arkansas, and Toronto. As the &lt;em&gt;first and only&lt;/em&gt; company to achieve fully driverless middle-mile commercial deliveries, Gatik holds a unique and defensible position in the AV industry, with a clear trajectory toward sustainable growth and profitability.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;We have delivered complete, proprietary AV technology - an integration of software and hardware - to enable earlier successes for our clients in constrained Level 4 autonomy.&amp;nbsp; By choosing the middle mile – with defined point-to-point delivery, we have simplified some of the more complex AV challenges, enabling us to achieve full autonomy ahead of competitors. Given extensive knowledge of Gatik’s well-defined, fixed route ODDs and hybrid architecture, we are able to hyper-optimize our models with exponentially less data, establish gate-keeping mechanisms to maintain explainability, and ensure continued safety of the system for unmanned operations.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Visit us at &lt;a href=&quot;http://gatik.ai/&quot;&gt;Gatik&lt;/a&gt; for more company information and &lt;a href=&quot;https://gatik.ai/careers/&quot;&gt;Careers at Gatik&lt;/a&gt; for more open roles.&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Notable News&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Bloomberg: &lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;a href=&quot;https://www.bloomberg.com/news/articles/2026-01-27/autonomous-trucking-firm-gatik-inks-contracts-worth-600-million&quot;&gt;Autonomous Trucking Firm Gatik Inks Contracts Worth $600 Million&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Forbes: &lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;a href=&quot;https://www.forbes.com/sites/alanohnsman/2026/01/28/hundreds-of-gatik-robot-delivery-trucks-headed-for-us-roads/?utm_campaign=ForbesMainLI&amp;amp;utm_source=ForbesMainLinkedIn&amp;amp;utm_medium=social&quot;&gt;Hundreds’ Of Gatik Robot Delivery Trucks Headed For U.S. Roads&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
