&lt;li style=&quot;font-weight: 300;&quot;&gt;&lt;span style=&quot;font-weight: 300; font-family: arial, helvetica, sans-serif;&quot;&gt;15 paid holidays&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;Daily lunches, snacks, and beverages available in all office locations&lt;/li&gt;
&lt;li style=&quot;font-weight: 300;&quot;&gt;&lt;span style=&quot;font-weight: 300; font-family: arial, helvetica, sans-serif;&quot;&gt;Pre-tax spending accounts for healthcare and dependent care expenses&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 300;&quot;&gt;&lt;span style=&quot;font-weight: 300; font-family: arial, helvetica, sans-serif;&quot;&gt;Pre-tax commuter benefits&lt;/span&gt;&lt;/li&gt;
